import org.apache.http.client.HttpClient
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

class BadFactory {
    fun bad(httpClient: HttpClient, newClient: HttpClient): HttpClient {
        val factory = HttpComponentsClientHttpRequestFactory(httpClient)
        factory.bufferRequestBody = false
        factory.setHttpClient(newClient)
        return factory.httpClient
    }
}

import org.apache.http.client.HttpClient
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

class GoodSetter {
    fun good(newClient: HttpClient): HttpClient {
        val factory = HttpComponentsClientHttpRequestFactory()
        factory.setHttpClient(newClient)
        return factory.httpClient
    }
}

import org.apache.http.client.HttpClient
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

class GoodConstructorOnly {
    fun good(httpClient: HttpClient): HttpClient {
        val factory = HttpComponentsClientHttpRequestFactory(httpClient)
        return factory.httpClient
    }
}
